const VALIDATION_RULES = {
  TITLE_MAX_LENGTH: 200,
  DESCRIPTION_MAX_LENGTH: 1000
} as const;

function validateTitle(title: string): boolean {
  return title && title.trim().length > 0 && title.length <= VALIDATION_RULES.TITLE_MAX_LENGTH;
}

function validateDescription(description: string | undefined): boolean {
  return !description || description.length <= VALIDATION_RULES.DESCRIPTION_MAX_LENGTH;
}

export function validateTodoInput(input: CreateTodoInput): boolean {
  return validateTitle(input.title) && validateDescription(input.description);
}

